def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

# Step 1: Find all prime pairs (p, q) such that p + q = 800 and p < q.
prime_pairs = []
for p in range(2, 400):
    if is_prime(p):
        q = 800 - p
        if is_prime(q) and p < q:
            prime_pairs.append((p, q))

print("Prime pairs (p, q) summing to 800:")
for p, q in prime_pairs:
    print(f"({p}, {q})")

# Step 2: For each pair (p, q), search for prime r.
results = []
for p, q in prime_pairs:
    found_r = []
    # r must satisfy q < r < 800
    for r in range(q + 1, 800):
        if is_prime(r):
            # Check conditions:
            # P1 = p+q-r = 800 - r (must be prime)
            P1 = 800 - r
            if not is_prime(P1):
                continue

            # P2 = q+r-p (must be prime)
            P2 = q + r - p
            if not is_prime(P2):
                continue

            # P3 = r+p-q (must be prime)
            P3 = r + p - q
            if not is_prime(P3):
                continue

            # P4 = p+q+r = 800 + r (must be prime)
            P4 = 800 + r
            if not is_prime(P4):
                continue

            # All conditions met
            found_r.append(r)

    if found_r:
        results.append(((p, q), found_r))

print("\nResults found:")
for (p, q), r_list in results:
    print(f"For (p, q) = ({p}, {q}), valid r values are: {r_list}")

